import {ArrowLeft,Heart,MapPin,Search,Star} from "lucide-react";import Link from "next/link";const vendors=[['Luma Studio','Photography','Addis Ababa','ETB 18k–45k','4.9','/images/wedding-hero.jpg'],['Garden House','Venue','Addis Ababa','ETB 65k–120k','4.8','/images/wedding-couple.jpg'],['Blush & Bloom','Decor + Flowers','Addis Ababa','ETB 12k–35k','4.9','/images/wedding-hero.jpg']];export default function Vendors(){return <div className="min-h-screen bg-cream"><header className="border-b border-black/[.06]"><div className="mx-auto flex max-w-6xl items-center gap-4 px-5 py-4"><Link href="/dashboard" className="grid size-10 place-items-center rounded-xl bg-white"><ArrowLeft size={18}/></Link><div><div className="eyebrow">Marketplace</div><h1 className="font-serif text-3xl">Find your vendors</h1></div></div></header><main className="mx-auto max-w-6xl px-5 py-6 pb-20"><div className="panel p-4"><div className="grid gap-3 md:grid-cols-[1.4fr_1fr_1fr_auto]"><div className="flex min-h-12 items-center gap-3 rounded-2xl bg-cream px-4 text-sm text-black/45"><Search size={17}/> Search photographer, venue...</div><div className="flex min-h-12 items-center gap-3 rounded-2xl bg-cream px-4 text-sm text-black/45"><MapPin size={17}/> Addis Ababa</div><div className="flex min-h-12 items-center gap-3 rounded-2xl bg-cream px-4 text-sm text-black/45">Category</div><button className="touch bg-teal text-white">Filter</button></div></div><div className="mt-5 grid gap-5 md:grid-cols-2 lg:grid-cols-3">{vendors.map(([name,type,city,price,rating,image])=><article key={name} className="overflow-hidden rounded-[26px] border border-black/[.06] bg-white shadow-card"><div className="relative h-64"><img src={image} alt="" className="h-full w-full object-cover"/><button className="absolute right-4 top-4 grid size-10 place-items-center rounded-full bg-white/90"><Heart size={18}/></button></div><div className="p-5"><div className="text-xs font-bold uppercase tracking-[.12em] text-teal/60">{type}</div><h2 className="mt-2 font-serif text-3xl">{name}</h2><div className="mt-2 flex items-center gap-2 text-sm text-black/45"><MapPin size={15}/> {city}</div><div className="mt-4 flex items-center justify-between"><span className="font-semibold">{price}</span><span className="inline-flex items-center gap-1 text-sm font-bold"><Star size={15} fill="currentColor" className="text-champagne"/> {rating}</span></div><button className="touch mt-5 w-full bg-navy text-white">View profile</button></div></article>)}</div></main></div>}
